#!/usr/bin/env python3
"""#3644: separate diagnostic profiles and sequential equal-path A/B timings."""
import hashlib, importlib.util, json, os, re, resource, statistics, subprocess, sys, time
from pathlib import Path
ROOT=Path.cwd()
WORK=ROOT/'_build/formal-reps-replay-2026-10-27'
sys.path.insert(0,str(ROOT/'bench/perf'))
from selfbuild_profiles import without_names
SUBJECTS={
 'flat':(str(WORK.relative_to(ROOT)/'flat.vibe'),'cli_main','0','0'),
 'compiler':('lib/@vibe/compiler/tests/codegen_lexer_test.vibe','__no_entry__','1','0'),
 'cli':('lib/@vibe/cli/entry.vibe','cli_main','1','1')}
def sha(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def write(path,v): Path(path).write_text(json.dumps(v,indent=2)+'\n')
def prepare(variant):
 gen=WORK/f'generation-{variant}'
 assert (gen/'stage2.wasm').read_bytes()==(gen/'stage3.wasm').read_bytes()
 folder=WORK/variant; folder.mkdir(exist_ok=False)
 raw=(gen/'stage2.wasm').read_bytes()
 (folder/'named.wasm').write_bytes(raw)
 (folder/'compiler.wasm').write_bytes(without_names(raw))
 assert len(without_names(raw))<len(raw)
 if variant=='a': (WORK/'flat.vibe').write_bytes((gen/'cli_adapter_module_source.vibe').read_bytes())
 write(folder/'receipt.json',dict(named_sha256=sha(folder/'named.wasm'),compiler_sha256=sha(folder/'compiler.wasm'),flat_input_sha256=sha(WORK/'flat.vibe'),own_flat_source_sha256=sha(gen/'cli_adapter_module_source.vibe'),fixpoint=True,generation=json.loads((gen/'generation.json').read_text())))
def run(subject,variant,index,temperature,profile=False,phase='timings'):
 folder=WORK/phase/str(index)/variant/subject
 folder.mkdir(parents=True,exist_ok=True)
 source,entry,fs,rc=SUBJECTS[subject]
 e={k:v for k,v in os.environ.items() if not k.startswith(('VIBE_','NODE_'))}
 e.update(VIBE_LIB=str(ROOT/'lib'),VIBE_PREOPEN_DIR=str(ROOT),VIBE_IMPORT_ABI='raw',VIBE_UNSTABLE='1',VIBE_RC=rc,VIBE_FS_COMPILE=fs,VIBE_BUILD_CACHE_DIR=str(folder/'cache'),VIBE_WASM_MEMORY_STATS='1',VIBE_CHECKED_MODULE_CACHE='off',VIBE_CODEGEN_BODY_CACHE='off',VIBE_EXPERIMENTAL_AST_CACHE='0',VIBE_FUNCTION_JOBS='1',VIBE_WASM_NAMES='0',VIBE_NODE_STACK_SIZE='131072',VIBE_INTERNAL_TRUSTED_SOURCE='1')
 if fs=='0': e['VIBE_DISABLE_PERSISTENT_ARTIFACT_CACHE']='1'
 if profile: e['VIBE_NODE_EXTRA_FLAGS']='\n'.join(['--cpu-prof',f'--cpu-prof-dir={folder}',f'--cpu-prof-name={temperature}.cpuprofile'])
 compiler=WORK/variant/('named.wasm' if profile else 'compiler.wasm')
 out=folder/f'{temperature}.wasm'
 assert not out.exists()
 cmd=['bash','scripts/run_wasm_vibe_host_runner.sh','--invoke','cli_main',str(compiler),source,str(out),entry]
 start=time.monotonic()
 with (folder/f'{temperature}.stdout').open('w') as stdout,(folder/f'{temperature}.stderr').open('w') as stderr:
  p=subprocess.run(cmd,cwd=ROOT,env=e,stdout=stdout,stderr=stderr,timeout=600)
 wall=time.monotonic()-start
 if p.returncode or not out.exists(): raise RuntimeError(f'{folder}: exit={p.returncode}')
 stats=re.findall(r'\[wasm-memory\][^\n]+',(folder/f'{temperature}.stderr').read_text())
 assert stats,f'missing memory stats {folder}'
 row=dict(subject=subject,variant=variant,round=index,temperature=temperature,wall_s=wall,compiler_sha256=sha(compiler),input=source,emitted_rc=rc,fs=fs,output_sha256=sha(out),output_bytes=out.stat().st_size,command=cmd,**{k:int(v) for k,v in re.findall(r'(pages|bytes|heap_ptr|rss)=([0-9]+)',stats[-1])})
 if subject=='flat': assert row['output_sha256']==sha(WORK/'a/compiler.wasm'),'flat output differs from frozen source compiler'
 return row

def baseline():
 rows=[]
 for profile in [False,True]:
  row=run('flat','a',0,'uncached',profile,'baseline-profile' if profile else 'baseline-wall')
  rows.append(row); write(WORK/'baseline.json',rows); print(json.dumps(row),flush=True)

def matrix():
 path=WORK/'timings.json'; assert not path.exists()
 rows=[]; expected={}
 for index in range(3):
  for subject in SUBJECTS:
   for variant in (['a','b'] if index%2==0 else ['b','a']):
    for temp in (['uncached'] if subject=='flat' else ['cold','warm']):
     row=run(subject,variant,index,temp)
     assert row['output_sha256']==expected.setdefault(subject,row['output_sha256']),f'output mismatch {row}'
     rows.append(row); write(path,dict(complete=False,runs=rows));print(json.dumps(row),flush=True)
 summaries=[]
 for subject in SUBJECTS:
  for temp in (['uncached'] if subject=='flat' else ['cold','warm']):
   pair={}
   for variant in ['a','b']:
    rs=[r for r in rows if (r['subject'],r['temperature'],r['variant'])==(subject,temp,variant)]
    pair[variant]=dict(n=len(rs),medians={k:statistics.median(r[k] for r in rs) for k in ['wall_s','heap_ptr','pages','rss','output_bytes']},wall_range_s=[min(r['wall_s'] for r in rs),max(r['wall_s'] for r in rs)],deterministic_heap=len(set(r['heap_ptr'] for r in rs))==1)
   summaries.append(dict(subject=subject,temperature=temp,variants=pair,changes_pct={k:100*(pair['b']['medians'][k]/pair['a']['medians'][k]-1) for k in ['wall_s','heap_ptr','pages','output_bytes']}))
 write(path,dict(complete=True,protocol='3 alternating AB/BA pairs; frozen input; equal-length paths; private cache per round/variant/subject; cold followed by warm; one process; separate CPU profiles',runs=rows,summaries=summaries));print(json.dumps(summaries,indent=2),flush=True)

def profiles():
 rows=[]
 # One baseline profile was captured before source edits. Complete three per variant.
 for index in range(3):
  for variant in (['a','b'] if index%2==0 else ['b','a']):
   row=run('flat',variant,index,'uncached',True,'profiles')
   rows.append(row);write(WORK/'profiles.json',dict(complete=False,runs=rows));print(json.dumps(row),flush=True)
 write(WORK/'profiles.json',dict(complete=True,runs=rows))

_, hard = resource.getrlimit(resource.RLIMIT_STACK)
resource.setrlimit(resource.RLIMIT_STACK, (hard, hard))
