assert sha(WORK/'b/compiler.wasm') == '9ab2c91a323c3433f0e6639870f750abc1264ff6bb7d917b29e3eea19a754ba5'
assert sha(WORK/'flat.vibe') == '341758297ab0d111b3dd2bb641069ef78cd8c73319ffec6d8fa1446e1cc05424'
assert sha(ROOT/'lib/@vibe/compiler/checker/checker_eq_unbounded_formal_msg.vibe') == 'da138553634b0be193d5906bdddfad97c6c976dd2f526617be47d9ff2c68a804'
assert sha(ROOT/'lib/@vibe/compiler/tests/formal_substitution_index_test.vibe') == 'a092a43a0507b825e1837e5054bcea652923533921118b0a573f6402df81263b'
